import { readFileSync } from 'fs';
import { join } from 'path';
import { IDQ_PROVINCES, IDQ_REGIONS } from './idq-provinces';

// The province list exists twice, generated by the same script: here, and
// with the map pixels in the client. This checks that the two still match,
// and that the map is drawable.
const CLIENT_GRID = join(
  __dirname,
  '../../../../client/src/idq/member-map/geo/italy-grid.json',
);

type ClientGrid = {
  cols: number;
  rows: number;
  regions: { code: string; name: string }[];
  provinces: {
    code: string;
    name: string;
    region: string;
    anchor: [number, number];
  }[];
  grid: string[];
};

function readClientGrid() {
  const data: ClientGrid = JSON.parse(readFileSync(CLIENT_GRID, 'utf8'));
  expect(data.grid).toHaveLength(data.rows);
  return {
    cols: data.cols,
    rows: data.grid,
    provinces: data.provinces,
    regions: data.regions,
  };
}

describe('IDQ provinces', () => {
  it('has the 107 ISTAT provinces, with unique codes, in 20 regions', () => {
    expect(IDQ_PROVINCES).toHaveLength(107);
    expect(new Set(IDQ_PROVINCES.map((p) => p.code)).size).toBe(107);
    expect(Object.keys(IDQ_REGIONS)).toHaveLength(20);
    for (const province of IDQ_PROVINCES) {
      expect(province.code).toMatch(/^[A-Z]{2}$/);
      expect(IDQ_REGIONS[province.region]).toBeDefined();
    }
  });

  it('matches the list of the client map', () => {
    const client = readClientGrid();
    expect(client.provinces).toEqual(
      IDQ_PROVINCES.map((p) => expect.objectContaining(p)),
    );
    // ("10" to "20" are integer keys: JavaScript lists them before "01")
    expect(client.regions).toEqual(
      Object.entries(IDQ_REGIONS)
        .map(([code, name]) => ({ code, name }))
        .sort((a, b) => a.code.localeCompare(b.code)),
    );
  });

  it('gives every province pixels on the map, and its pin one of them', () => {
    const { cols, rows, provinces } = readClientGrid();
    const codeAt = (x: number, y: number) => rows[y].slice(x * 2, x * 2 + 2);

    const known = new Set(provinces.map((p) => p.code));
    const pixels = new Map<string, number>();
    for (const row of rows) {
      expect(row).toHaveLength(cols * 2);
      for (let x = 0; x < cols; x++) {
        const code = row.slice(x * 2, x * 2 + 2);
        if (code === '..') continue;
        expect(known).toContain(code);
        pixels.set(code, (pixels.get(code) ?? 0) + 1);
      }
    }

    for (const province of provinces) {
      expect(pixels.get(province.code)).toBeGreaterThan(0);
      const [x, y] = province.anchor;
      expect(codeAt(Math.floor(x), Math.floor(y))).toBe(province.code);
    }
  });
});
